function nationalCodeValidate(n){const t=n;if(t.length===10){if(t==="1111111111"||t==="2222222222"||t==="3333333333"||t==="4444444444"||t==="5555555555"||t==="6666666666"||t==="7777777777"||t==="8888888888"||t==="9999999999")return!1;const r=+t.charAt(0)*10,u=+t.charAt(1)*9,f=+t.charAt(2)*8,e=+t.charAt(3)*7,o=+t.charAt(4)*6,s=+t.charAt(5)*5,h=+t.charAt(6)*4,c=+t.charAt(7)*3,l=+t.charAt(8)*2,i=+t.charAt(9),a=r+u+f+e+o+s+h+c+l,n=a%11;return n<2&&i===n||n>=2&&11-n===i}}